const {chromium}=require('/Users/ph.qian/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');const fs=require('node:fs/promises'),assert=require('node:assert/strict');
(async()=>{const browser=await chromium.launch({executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:true});try{const page=await browser.newPage({viewport:{width:1440,height:1000}});await page.goto(process.env.VDOC_TEST_URL||'http://127.0.0.1:4178/');await page.getByRole('button',{name:'New document',exact:true}).click();const body=page.getByRole('textbox',{name:'Document body',exact:true});await body.fill('Focus continuity 中文');await page.waitForTimeout(800);const cases=[['Insert','Image from device'],['Insert','Link'],['Format','Page setup'],['Format','Paragraph layout'],['Format','Paragraph borders…'],['File','Language…'],['File','Open local document'],['View','Word count'],['View','Keyboard shortcuts']];const results=[];for(const [menu,item] of cases){const before=await page.evaluate(()=>window.vdoc.snapshot().document);await page.getByRole('button',{name:menu,exact:true}).click();await page.getByRole('menuitem',{name:item,exact:true}).click();await page.getByRole('dialog').waitFor();await page.waitForTimeout(250);assert(await page.getByRole('dialog').evaluate(el=>el.contains(document.activeElement)),item+' initial focus');await page.keyboard.press('Escape');await page.getByRole('dialog').waitFor({state:'hidden'});await page.waitForTimeout(100);assert(await body.evaluate(el=>el===document.activeElement),item+' returned focus');await page.keyboard.type('Z');await page.waitForTimeout(80);const after=await page.evaluate(()=>window.vdoc.snapshot().document);assert.notDeepEqual(after,before,item+' accepts real typing');await page.getByRole('button',{name:'Undo · ⌘Z',exact:true}).click();assert.deepEqual(await page.evaluate(()=>window.vdoc.snapshot().document),before,item+' typing undo exact');results.push({menu,item,initialDialogFocus:true,returnedEditorFocus:true,realTypingAndExactUndo:true});console.log(item+' passed');}await fs.writeFile('tests/fixtures/combined-workflow-20261010/dialog-focus-matrix.json',JSON.stringify({browser:browser.version(),origin:page.url(),results},null,2));}finally{await browser.close();}})().catch(e=>{console.error(e);process.exitCode=1;});
